export const dynamicParams = true

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])

    if (!postRes.ok) {
      return null
    }

    const post = (await postRes.json()) as Post
    const comments = (await commentsRes.json()) as Comment[]
    return { post, comments }
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>
}): Promise<Metadata> {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    return { title: 'Post Not Found' }
  }

  return {
    title: `${data.post.title} - My Blog`,
    description: data.post.body.substring(0, 160),
    openGraph: {
      title: data.post.title,
      description: data.post.body.substring(0, 160),
    },
  }
}

export default async function BlogPostPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <Link href="/blog">← Back</Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import type { NextRequest } from 'next/server'

type Post = {
  id: number
  title: string
  content: string
}

const posts: Post[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

export async function GET() {
  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  const body = (await request.json()) as { title?: string; content?: string }

  if (!body.title || !body.content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: Post = {
    id: Date.now(),
    title: body.title,
    content: body.content,
  }

  return Response.json(newPost, { status: 201 })
}

import type { NextRequest } from 'next/server'

type Post = {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params

  const post: Post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const body = (await request.json()) as { title?: string; content?: string }

  const updatedPost: Post = {
    id: parseInt(id),
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

